import csv
import io
import re
from typing import Any


_NUMBER = re.compile(
    r"""^[\s]*[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?[\s]*$"""
)


def _is_number(value: str) -> bool:
    return bool(_NUMBER.match(value))


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = []

    try:
        for row in reader:
            if row and any(cell.strip() for cell in row):
                records.append(row)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 2
    header_index = None

    for index, row in enumerate(records):
        if len(row) < expected_width or all(_is_number(cell) for cell in row):
            continue

        for following in records[index + 1:]:
            if following and _is_number(following[0]):
                header_index = index
                break
            if following and not _is_number(following[0]):
                break
        if header_index is not None:
            break

    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(records) if len(row) >= expected_width),
            0,
        )

    columns = records[header_index]
    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
